import{_ as a,o as s,c as t,a2 as l}from"./chunks/framework.CNDaxUod.js";const h=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),i={name:"changelog.md"};function o(n,e,r,u,m,c){return s(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>Thank you for using the SCTP! Download the newest mod files via the website. Newest updates are at the top.</p><h2 id="_2-4-rare-dle-in-game-auctions-and-wishlists" tabindex="-1">2.4: Rare-dle in-game, auctions and wishlists <a class="header-anchor" href="#_2-4-rare-dle-in-game-auctions-and-wishlists" aria-label="Permalink to &quot;2.4: Rare-dle in-game, auctions and wishlists&quot;">​</a></h2><details class="details custom-block"><summary>Rare-dle in-game</summary><ul><li>Play today&#39;s Rare-dle without leaving the game: open the menu (X) and pick the new Rare-dle tile.</li><li>It&#39;s the same puzzle, streak and leaderboard as on the website, on your sctp.nl account. No password needed: it uses the sctp.nl account linked to your Minecraft name.</li></ul></details><details class="details custom-block"><summary>Empty hand for doors and chests</summary><ul><li>Got an item that does something when you right-click (a rare, a tool)? Add it in Settings › Empty hand: press Add, hold the item, press X.</li><li>From then on, clicking doors, chests, buttons and other blocks uses an empty hand instead, so the item doesn&#39;t go off. Sneak-click to use the item on purpose.</li></ul></details><details class="details custom-block"><summary>Double chest shops</summary><ul><li>Double chests are scanned now too. The sign on the left half is the price (the right half&#39;s sign counts if the left has none).</li></ul></details><details class="details custom-block"><summary>New highlights</summary><ul><li>When something sold from your shop, the chest gets a bright green outline you can see through walls.</li><li>New teleport styles: a chest outline that shows through walls, or a real beacon beam rising out of the shop.</li><li>Empty shops you just walked past get a grey marker instead of red.</li></ul></details><details class="details custom-block"><summary>Real sales</summary><ul><li>&quot;Sold&quot; on the website now only counts real sales: stock that went down while the payment showed up in that chest. Restocking or taking items out no longer looks like a sale.</li></ul></details><details class="details custom-block"><summary>Stock holograms</summary><ul><li>Turn on Settings › Look &amp; tools › Stock holograms to see a small &quot;64 in stock&quot; line on the front of shop chests you&#39;ve scanned. Off by default.</li></ul></details><details class="details custom-block"><summary>Smaller things</summary><ul><li>The ender chest / backpack arrows are now one button with an icon.</li><li>Hide [DISPLAY] shops in your searches: the Display chip on the Listings screen, or Settings.</li></ul></details><details class="details custom-block"><summary>Website: auctions and wishlists</summary><ul><li>Rare auctions at sctp.nl/auction: enter your rares in a quick table, set your prices or let the host pick, and see where to drop off your shulker. The homepage shows the next auction.</li><li>Star the rares and mapart you want on My Collection to make a wishlist, and share it with a link.</li><li>Shop Logger is on Modrinth now!</li></ul></details><h2 id="_2-3-all-new-mod-menus" tabindex="-1">2.3: all-new mod menus <a class="header-anchor" href="#_2-3-all-new-mod-menus" aria-label="Permalink to &quot;2.3: all-new mod menus&quot;">​</a></h2><details class="details custom-block"><summary>A brand new look</summary><ul><li>Every Shop Logger screen was redesigned to match the website: dark green cards, lime accents, real on/off switches and cleaner lists.</li><li>All the old features are still there, just easier to find and read!</li></ul></details><details class="details custom-block"><summary>Easier to get around</summary><ul><li>Every screen has a top bar with tabs, so you can jump straight to Listings, Items, Rares, Watchlist, Marketplace, Mapart or Settings.</li><li>Pressing X now opens a dashboard: your world, scanner and watchlist at a glance, a search box that goes straight to the listings, and a tile for every section.</li></ul></details><details class="details custom-block"><summary>One Settings screen</summary><ul><li>Settings and Advanced settings are now one screen, grouped into categories (Scanning, Alerts, Look &amp; tools, Data, Advanced).</li><li>Every option has a short explanation, and the rescan cooldown is a simple - / + stepper.</li></ul></details><details class="details custom-block"><summary>Better item pages</summary><ul><li>Item pages now have tabs: current listings, price history and (for rares) all the details.</li></ul></details><details class="details custom-block"><summary>Ender chest ⇄ backpack</summary><ul><li>Arrows on either side of your ender chest and backpack screens switch between them (/ec and /bp). Don&#39;t want them? Turn them off in Settings.</li></ul></details><details class="details custom-block"><summary>Colour themes</summary><ul><li>Choose from 10 colour themes for the mod&#39;s menus in Settings: Snail, Ocean, Amethyst, Sakura, Honey, Pumpkin, Crimson, Frost, Firefly and Graphite.</li></ul></details><details class="details custom-block"><summary>Easier filters</summary><ul><li>Click any filter to pick from a list (with a search box for long lists) instead of clicking through every option.</li><li>Rare items can now be filtered by release year or month, instead of by dyeable.</li><li>Going back from an item page keeps your scroll position.</li></ul></details><details class="details custom-block"><summary>More in-game</summary><ul><li>Add an item to your watchlist, or change its watchlist settings, straight from its item page.</li><li>The in-game marketplace can be filtered by world and by Selling / Looking for.</li><li>New teleport highlight: a glowing outline around the shop&#39;s chest instead of a beam.</li><li>The mapart scanner is off by default for now. Enabling this feature will capture all maps in item frames visible to you.</li></ul></details><details class="details custom-block"><summary>Fixes</summary><ul><li>Scans no longer report a shop&#39;s old price after the seller changed the sign.</li></ul></details><details class="details custom-block"><summary>Website</summary><ul><li>Like your favourite mapart, and sort the catalog by most liked.</li><li>Fixed &quot;Mine&quot; on the marketplace sometimes asking you to log in while you were logged in.</li></ul></details><details class="details custom-block"><summary>Marketplace</summary><ul><li>You can now write a review on job posts, not just give a thumbs up or down.</li><li>Renew your own listings and job posts for another 14 days with one click, instead of posting them again.</li></ul></details><h2 id="_2-2-2-2-1" tabindex="-1">2.2 &amp; 2.2.1 <a class="header-anchor" href="#_2-2-2-2-1" aria-label="Permalink to &quot;2.2 &amp; 2.2.1&quot;">​</a></h2><details class="details custom-block"><summary>Smarter scanning</summary><ul><li>The auto-scanner adjusts its speed to your connection: quick when things are smooth, slower during lag.</li><li>Fixed items sometimes being logged at the wrong chest when another screen opened at the same moment.</li><li>Double chests are never scanned, since shops can&#39;t be double chests.</li></ul></details><details class="details custom-block"><summary>Website</summary><ul><li>Mapart can now have up to 5 keywords, a flat / staircased type, and there&#39;s a new Games category.</li><li>Collab mapart can list up to 16 artists.</li></ul></details><details class="details custom-block"><summary>/preview formatting codes</summary><ul><li>/preview now understands bold, italic, strikethrough, underlined and obfuscated codes (thanks ZyskiDev!).</li></ul></details><h2 id="_2-1" tabindex="-1">2.1 <a class="header-anchor" href="#_2-1" aria-label="Permalink to &quot;2.1&quot;">​</a></h2><details class="details custom-block"><summary>/preview</summary><ul><li>Hold an item and run /preview with a name to see a coloured rename on it before you pay for the real thing. It&#39;s only visible to you.</li></ul></details><h2 id="v1-6-v2" tabindex="-1">V1.6 &gt; V2 <a class="header-anchor" href="#v1-6-v2" aria-label="Permalink to &quot;V1.6 &gt; V2&quot;">​</a></h2><p>We updated to V2 on the 22nd of September.</p><h3 id="website" tabindex="-1">Website <a class="header-anchor" href="#website" aria-label="Permalink to &quot;Website&quot;">​</a></h3><details class="details custom-block"><summary>Mapart!</summary><ul><li>The website now has the full in-game mapart museum, but digital!</li><li>As mapart seller, you can verify your account to manage your own maps!</li></ul></details><details class="details custom-block"><summary>Collections!</summary><ul><li>You can now mark mapart and rares as having them in your collection!</li><li>You can share your collection with others via a link, and you can see a ton of stats by clicking on your username!</li></ul></details><details class="details custom-block"><summary>Marketplace additions!</summary><ul><li>You can now post jobs on the marketplace!</li><li>You can review listings/sellers now!</li></ul></details><details class="details custom-block"><summary>Rare-dle!</summary><ul><li>You can now play a variation on wordle, but based on our SC rares catalog: rare-dle!</li><li>A new rare is chosen every day!</li></ul></details><details class="details custom-block"><summary>QOL/fixes</summary><ul><li>Hide columns from the search table</li><li>Price filter can now convert to diamond-equivalent</li><li>Typo suggestions where needed</li><li>Mapart of the day on the home page</li><li>Navigation bar redesigned</li></ul></details><h3 id="mod" tabindex="-1">Mod <a class="header-anchor" href="#mod" aria-label="Permalink to &quot;Mod&quot;">​</a></h3><details class="details custom-block"><summary>Mapart Scanner</summary><ul><li>The mod now has a built in mapart scanning feature that uploads straight to the gallery!</li></ul></details><details class="details custom-block"><summary>Watchlist QOL</summary><ul><li>You can now ignore listings in your watchlist</li><li>General usage of watchlist has been improved.</li></ul></details><details class="details custom-block"><summary>In-game reporting</summary><ul><li>You can now report all listings via in-game menu&#39;s!</li></ul></details><details class="details custom-block"><summary>Small extras</summary><ul><li>Rare rentals info can now be toggled on for shulkers</li><li>Fly and rank tokens no longer redeem automatically</li></ul></details>',42)])])}const g=a(i,[["render",o]]);export{h as __pageData,g as default};
